import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  root.userData.handlers = {};

  const gradientMaterial = new MeshBasicNodeMaterial();
  const gradientUv = uv();
  gradientMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.0, 1.0, gradientUv.y)
  );

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdrop = new Mesh(backdropGeometry, gradientMaterial);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdropGeometry, gradientMaterial);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadowGeometry = new CircleGeometry(1.55, 48);
  const shadow = new Mesh(shadowGeometry, shadowMaterial);
  shadow.scale.set(1.25, 0.42, 1);
  shadow.position.set(0, -0.88, -0.12);
  root.add(shadow);
  resources.push(shadowGeometry, shadowMaterial);

  const cardWidth = 2.55;
  const cardHeight = 1.6;
  const cardGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const cardMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2'
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.set(0, 0, 0);
  root.add(card);
  resources.push(cardGeometry, cardMaterial);

  const frameMaterial = new MeshBasicNodeMaterial({
    color: '#16161d'
  });
  const frameGeometry = new BoxGeometry(cardWidth + 0.08, cardHeight + 0.08, 0.045);
  const frame = new Mesh(frameGeometry, frameMaterial);
  frame.position.set(0, 0, -0.035);
  root.add(frame);
  resources.push(frameGeometry, frameMaterial);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const accentGeometry = new BoxGeometry(0.08, 0.72, 0.055);
  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-cardWidth * 0.5 + 0.2, 0.02, 0.045);
  root.add(accent);
  resources.push(accentGeometry, accentMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    if (!item || typeof item.text !== 'string' || item.text.length === 0) continue;
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 0.13,
      color: item.role === 'accent' ? '#ff2a38' : '#e8ecf2',
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });
    textObject.position.set(-0.92, -0.58, 0.08);
    root.add(textObject);
  }

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (typeof imageUrl === 'string' && imageUrl.length > 0) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      texture.colorSpace = 'srgb';
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
      resources.push(texture);
    }).catch(() => {});
  }

  const primitives = config.cinematicPrimitives ?? [];
  const primitiveResults = [];
  for (const primitive of primitives) {
    if (!primitive || !primitive.name || !ctx.primitives?.[primitive.name]) continue;
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const result of primitiveResults) {
      result?.cleanup?.();
      result?.timeline?.kill?.();
    }

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    root.traverse((object) => {
      if (object !== root) {
        object.geometry?.dispose?.();
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => material?.dispose?.());
        } else {
          object.material?.dispose?.();
        }
      }
    });

    root.clear();
  };

  return root;
}
